#include <iostream>
using namespace std;

int main() {
    float perimetro;
    float altezza;
    float area;
    float base;

    cout << "Inserire perimetro: ";
    cin >> perimetro;

    cout << "Inserire altezza: ";
    cin >> altezza;

    base = (perimetro / 2.0) - altezza;
    area = base * altezza;

    cout << "L'area e': " << area << endl;

    return 0;
}
